 "content": "def transform(grid):
    """Color each connected input object with its motif decomposition."""
    from collections import deque

    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    seen = set()
    # L triomino shapes and color identities from the demonstrations.
    l_shapes = {
        2: {(0, 1), (1, 0), (1, 1)},
        3: {(0, 0), (0, 1), (1, 1)},
        4: {(0, 0), (1, 0), (1, 1)},
    }
    square = {(0, 0), (0, 1), (1, 0), (1, 1)}

    def norm(points):
        r0 = min(r for r, c in points)
        c0 = min(c for r, c in points)
        return frozenset((r-r0, c-c0) for r, c in points)

    def orientations(shape):
        result = set()
        points = set(shape)
        for _ in range(4):
            result.add(norm(points))
            points = {(c, -r) for r, c in points}
        return result

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = set()
            while q:
                y, x = q.popleft()
                component.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 8 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            remaining = set(component)
            placements = []
            for color, motif in [(1, square)] + list(l_shapes.items()):
                for shape in orientations(motif):
                    sh, sw = max(y for y,x in shape)+1, max(x for y,x in shape)+1
                    for y in range(h-sh+1):
                        for x in range(w-sw+1):
                            cells = {(y+dy,x+dx) for dy,dx in shape}
                            if cells <= component:
                                placements.append((color, cells))
            def tile(left, chosen):
                if not left:
                    return chosen
                cell = min(left)
                for color, cells in placements:
                    if cell in cells and cells <= left:
                        result = tile(left-cells, chosen+[(color,cells)])
                        if result is not None:
                            return result
                return None
            pieces = tile(remaining, [])
            if pieces:
                for color, cells in pieces:
                    for y, x in cells:
                        out[y][x] = color
    return out

